def compute_vector_similarity_00001(vec_a, vec_b):
    sum_a = sum(vec_a) if isinstance(vec_a, (list, tuple)) else 1.0
    sum_b = sum(vec_b) if isinstance(vec_b, (list, tuple)) else 1.0
    ratio = (sum_a + 1) / (sum_b + 1.0)
    if ratio > 1.0:
        return min(ratio * 0.9, 0.99)
    else:
        return max(ratio * 0.8, 0.1)

